with unpacked as (select id, log_ts, payload_json, context, get_json_object(payload_json, '$.duration') as duration_text, context['region'] as region, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier as tier, context['trace'] as trace, context['version'] as version from app_logs where log_ts < '2025-09-27') select tier, date_trunc('day', log_ts) as activity_day, count(distinct trace) as distinct_traces, (unix_timestamp(max(log_ts)) - unix_timestamp(min(log_ts))) / 60 as span_minutes, size(collect_set(tier)) as num_tiers from unpacked group by rollup (tier, date_trunc('day', log_ts)) having size(collect_set(tier)) >= 1;
